export const postgresCatalogQueriesV2 = Object.freeze({
  schemas: `SELECT n.nspname AS name,CASE WHEN n.nspowner=(SELECT oid FROM pg_roles WHERE rolname=session_user) THEN '$owner' ELSE pg_get_userbyid(n.nspowner) END AS owner,
    (SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN a.grantor=n.nspowner THEN '$owner' ELSE pg_get_userbyid(a.grantor) END,CASE WHEN a.grantee=0 THEN 'PUBLIC' WHEN a.grantee=n.nspowner THEN '$owner' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY a.grantor=n.nspowner,a.grantee=0,a.grantee=n.nspowner,pg_get_userbyid(a.grantee),a.privilege_type),'[]'::jsonb) FROM aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a) AS acl
    FROM pg_namespace n WHERE n.nspname IN ('dream','dream_migrations') ORDER BY n.nspname`,
  relations: `SELECT n.nspname AS schema,c.relname AS name,c.relkind,c.relrowsecurity,c.relforcerowsecurity,
    CASE WHEN c.relowner=(SELECT oid FROM pg_roles WHERE rolname=session_user) THEN '$owner' ELSE pg_get_userbyid(c.relowner) END AS owner,
    c.relreplident,c.relpersistence,c.relispartition,c.reloptions,
    (SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN a.grantor=c.relowner THEN '$owner' ELSE pg_get_userbyid(a.grantor) END,CASE WHEN a.grantee=0 THEN 'PUBLIC' WHEN a.grantee=c.relowner THEN '$owner' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY a.grantor=c.relowner,a.grantee=0,a.grantee=c.relowner,pg_get_userbyid(a.grantee),a.privilege_type),'[]'::jsonb) FROM aclexplode(coalesce(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 'S'::"char" ELSE 'r'::"char" END,c.relowner))) a) AS acl
    FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('dream','dream_migrations') AND c.relkind NOT IN ('i','I','t') ORDER BY n.nspname,c.relname`,
  columns: `SELECT n.nspname AS schema,c.relname AS table,a.attnum AS ordinal,a.attname AS name,format_type(a.atttypid,a.atttypmod) AS type,a.attnotnull,a.attidentity,a.attgenerated,a.attisdropped,
    pg_get_expr(d.adbin,d.adrelid,false) AS default_expr,
    CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::regcollation::text END AS collation,
    (SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN p.grantor=c.relowner THEN '$owner' ELSE pg_get_userbyid(p.grantor) END,CASE WHEN p.grantee=0 THEN 'PUBLIC' WHEN p.grantee=c.relowner THEN '$owner' ELSE pg_get_userbyid(p.grantee) END,p.privilege_type,p.is_grantable) ORDER BY p.grantor=c.relowner,p.grantee=0,p.grantee=c.relowner,pg_get_userbyid(p.grantee),p.privilege_type),'[]'::jsonb) FROM aclexplode(a.attacl) p) AS acl
    FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
    WHERE n.nspname IN ('dream','dream_migrations') AND c.relkind IN ('r','p','v','m','f') AND a.attnum>0 ORDER BY n.nspname,c.relname,a.attnum`,
  constraints: `SELECT n.nspname AS schema,coalesce(c.relname,t.typname) AS object,k.conname AS name,k.contype,k.condeferrable,k.condeferred,k.convalidated,pg_get_constraintdef(k.oid,false) AS definition
    FROM pg_constraint k JOIN pg_namespace n ON n.oid=k.connamespace LEFT JOIN pg_class c ON c.oid=k.conrelid LEFT JOIN pg_type t ON t.oid=k.contypid
    WHERE n.nspname IN ('dream','dream_migrations') ORDER BY n.nspname,coalesce(c.relname,t.typname),k.conname`,
  indexes: `SELECT n.nspname AS schema,c.relname AS table,i.relname AS name,x.indisunique,x.indisprimary,x.indisvalid,x.indisready,x.indislive,pg_get_indexdef(x.indexrelid,0,false) AS definition
    FROM pg_index x JOIN pg_class c ON c.oid=x.indrelid JOIN pg_class i ON i.oid=x.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname IN ('dream','dream_migrations') ORDER BY n.nspname,c.relname,i.relname`,
  policies: `SELECT n.nspname AS schema,c.relname AS table,p.polname AS name,p.polpermissive,p.polcmd,
    (SELECT jsonb_agg(CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END ORDER BY CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END) FROM unnest(p.polroles) r) AS roles,
    pg_get_expr(p.polqual,p.polrelid,false) AS using_expr,pg_get_expr(p.polwithcheck,p.polrelid,false) AS check_expr
    FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('dream','dream_migrations') ORDER BY n.nspname,c.relname,p.polname`,
  triggers: `SELECT n.nspname AS schema,c.relname AS table,t.tgname AS name,t.tgenabled,t.tgdeferrable,t.tginitdeferred,t.tgtype,
    pn.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')' AS function,pg_get_triggerdef(t.oid,false) AS definition
    FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace
    WHERE n.nspname IN ('dream','dream_migrations') AND NOT t.tgisinternal ORDER BY n.nspname,c.relname,t.tgname`,
  functions: `SELECT n.nspname AS schema,p.proname AS name,pg_get_function_identity_arguments(p.oid) AS arguments,pg_get_function_arguments(p.oid) AS declared_arguments,pg_get_function_result(p.oid) AS result,l.lanname AS language,
    CASE WHEN p.proowner=(SELECT oid FROM pg_roles WHERE rolname=session_user) THEN '$owner' ELSE pg_get_userbyid(p.proowner) END AS owner,
    p.prokind,p.prosecdef,p.proleakproof,p.proisstrict,p.proretset,p.provolatile,p.proparallel,p.proconfig,
    encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') AS body_sha256,
    (SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN a.grantor=p.proowner THEN '$owner' ELSE pg_get_userbyid(a.grantor) END,CASE WHEN a.grantee=0 THEN 'PUBLIC' WHEN a.grantee=p.proowner THEN '$owner' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY a.grantor=p.proowner,a.grantee=0,a.grantee=p.proowner,pg_get_userbyid(a.grantee),a.privilege_type),'[]'::jsonb) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a) AS acl
    FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname IN ('dream','dream_migrations') ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)`,
  types: `SELECT n.nspname AS schema,t.typname AS name,t.typtype,format_type(t.typbasetype,t.typtypmod) AS base,t.typnotnull,t.typdefault,
    CASE WHEN t.typowner=(SELECT oid FROM pg_roles WHERE rolname=session_user) THEN '$owner' ELSE pg_get_userbyid(t.typowner) END AS owner,
    (SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN a.grantor=t.typowner THEN '$owner' ELSE pg_get_userbyid(a.grantor) END,CASE WHEN a.grantee=0 THEN 'PUBLIC' WHEN a.grantee=t.typowner THEN '$owner' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY a.grantor=t.typowner,a.grantee=0,a.grantee=t.typowner,pg_get_userbyid(a.grantee),a.privilege_type),'[]'::jsonb) FROM aclexplode(coalesce(t.typacl,acldefault('T',t.typowner))) a) AS acl
    FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname IN ('dream','dream_migrations') AND t.typrelid=0 AND t.typelem=0 ORDER BY n.nspname,t.typname`,
});
export async function readPostgresCatalogV2(client: Reader) {
  const catalog: Record<string, unknown> = {};
  // One client, sequential statements; caller owns its stable inspection transaction.
  for (const [key, query] of Object.entries(postgresCatalogQueriesV2)) catalog[key] = (await client.query(query)).rows;
  return catalog;
}

